import{_ as e,o,c as a,a2 as u}from"./chunks/framework.Crpw6aS5.js";const _=JSON.parse('{"title":"1986年 · 资本配置的哲学","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1986年.md","filePath":"05_quotes/by-year/1986年.md"}'),r={name:"05_quotes/by-year/1986年.md"};function l(q,t,s,c,p,i){return o(),a("div",null,[...t[0]||(t[0]=[u('<h1 id="_1986年-·-资本配置的哲学" tabindex="-1">1986年 · 资本配置的哲学 <a class="header-anchor" href="#_1986年-·-资本配置的哲学" aria-label="Permalink to &quot;1986年 · 资本配置的哲学&quot;">​</a></h1><blockquote><p>&quot;查理和我其实只有两个工作：一个是吸引留住出色经理运营我们各个业务，这其实不难，通常我们买公司的时候，经理早就证明了自己才能；我们主要贡献就是别挡道。&quot;——巴菲特（56岁）</p></blockquote><p>本页收录1986年致股东信中的经典语录。巴菲特在这一年系统阐述了伯克希尔的管理哲学——找对人、不挡道，并解释了为什么市场高估时宁愿持有现金等待，而非胡乱出手。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;我们坚持只和我们喜欢欣赏的人合作，这个政策不仅最大化好结果概率，还能让我们过得特别开心。和让你胃不舒服的人合作，就像为了钱结婚，本来就不对，你已经有钱了，还这么干，绝对疯了。&quot;</p></blockquote><blockquote><p>&quot;我们读过很多管理学著作，精确规定一个高管管多少人，我们觉得没道理。你有能力品格好热情的经理管理自己 passion所在business，你让十几个直接汇报给你，你下午还能nap；反过来，哪怕一个人欺骗无能没兴趣，你管一个都麻烦。&quot;</p></blockquote><blockquote><p>&quot;好骑师骑好马才能赢，骑破马赢不了。过去我慢慢学，很多次才学会。还有，institutional imperative这个看不见的力量太重要了，原来，机构惯性就是，企业就像牛顿第一运动定律，原来方向一直不变。&quot;</p></blockquote><blockquote><p>&quot;我很多年前写过：&#39;当名声卓越的管理层接手名声差的fundamenta生意，名声坏的还是business保持完好。&#39;这个观点这么多年没变。&quot;</p></blockquote><blockquote><p>&quot;查理和我做50个类似决策，大概能对40多个，判断现在这个机会，期望收益挺不错，错了也不会对伯克希尔造成致命伤害。大多数经理，没动力做这种聪明但有概率看起来像傻子的决策：做成了也就拍一下肩，做错了炒鱿鱼。&quot;</p></blockquote><blockquote><p>&quot;我们保险投资还是集中，WPPSS就是例子，只有财务特别强才能这么做，对几乎所有其他保险公司，这么集中都完全不合适。&quot;</p></blockquote><blockquote><p>&quot;现在牛市，大家都兴奋，但是记住，整体投资者长期回报不可能超过企业整体盈利，交易成本管理费吃掉很多，所以投资者回报一定低于企业盈利。牛市掩盖不了这个数学规律，改变不了。&quot;</p></blockquote><blockquote><p>&quot;我们三大重仓股首都城市/ABC、GEICO、华盛顿邮报，我们永远不卖，不管高估低估，就像我们不卖喜诗糖果、水牛城新闻，我们就是要拿着好生意不动。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1986年伯克希尔净值增长4.925亿美元，增幅26.1%，过去二十二年复合增长率23.3%。巴菲特收购了Fechheimer Bros.（制服制造商），继续扩大&quot;圣人&quot;阵容。GEICO业绩出色，卢·辛普森的投资记录持续跑赢大盘。1986年税改法案落地，巴菲特分析了其对伯克希尔的整体负面影响，并预判行业产能过剩必将再次来临。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1986年/翻译.html">01_letters/1986年/翻译</a> · <a href="/01_letters/1986年/核心总结.html">01_letters/1986年/核心总结</a> · <a href="/01_letters/1986年/思维导图.html">01_letters/1986年/思维导图</a></p>',19)])])}const h=e(r,[["render",l]]);export{_ as __pageData,h as default};
